import{_ as a,g as e,e as r,a4 as d}from"./chunks/framework.CEYJDsBW.js";const f=JSON.parse('{"title":"数据包与资源包","description":"","frontmatter":{},"headers":[],"relativePath":"ageratum/21.1/packs/index.md","filePath":"ageratum/21.1/packs/index.md"}'),n={name:"ageratum/21.1/packs/index.md"};function c(o,t,l,h,i,m){return e(),r("div",null,[...t[0]||(t[0]=[d('<h1 id="数据包与资源包" tabindex="-1">数据包与资源包 <a class="header-anchor" href="#数据包与资源包" aria-label="Permalink to &quot;数据包与资源包&quot;">​</a></h1><p>Ageratum 在客户端资源重载时读取手册。发布给其他玩家时，把 Markdown、插图和结构预览随模组资源或客户端资源包一起分发。服务端可以通知玩家打开某个文档 ID，正文来自玩家本机。</p><table tabindex="0"><thead><tr><th>要做的事</th><th>入口</th></tr></thead><tbody><tr><td>从空目录创建手册，检查语言回退和预览</td><td><a href="./layout.html">资源包布局</a></td></tr><tr><td>修改目录标题、排序和颜色</td><td><a href="./metadata.html">页面元数据</a></td></tr><tr><td>让玩家从特定物品或物品组件进入文章</td><td><a href="./bindings.html">物品绑定</a></td></tr><tr><td>插入提示、目录、布局和公式</td><td><a href="./blocks.html">块标签与排版</a></td></tr><tr><td>展示物品、方块、实体及实际配方</td><td><a href="./content.html">游戏对象与配方</a></td></tr><tr><td>使用本地化文本、按键、交互样式和图片</td><td><a href="./inline.html">行内标记与图片</a></td></tr><tr><td>在页面中预览 NBT 或 SNBT</td><td><a href="./structures.html">结构预览与字段</a></td></tr><tr><td>投影结构或导出到存档</td><td><a href="./export.html">结构投影与导出</a></td></tr></tbody></table><p>手册注册表在代码中登记组件工厂，资源包作者通过标签使用这些工厂。普通服务端数据包的 <code>data/</code> 目录没有独立的手册发现或组件注册入口。文中展示服务器配方时，配方本身仍由游戏的配方管理器加载。<a href="https://github.com/Anvil-Dev/Ageratum/blob/83f89c4c3a6796d16bcef7e728f4b5b95d5a516c/src/main/java/dev/anvilcraft/resource/ageratum/client/feat/markdown/GuideDocumentCache.java" target="_blank" rel="noreferrer">文档缓存</a> · <a href="https://github.com/Anvil-Dev/Ageratum/blob/83f89c4c3a6796d16bcef7e728f4b5b95d5a516c/src/main/java/dev/anvilcraft/resource/ageratum/client/AgeratumClient.java" target="_blank" rel="noreferrer">客户端注册</a></p>',4)])])}const u=a(n,[["render",c]]);export{f as __pageData,u as default};
